1	// The fleet-baseline DISPATCH — the enforcer's manual lever over the whole fleet:
2	// force every covered member to baseline NOW, instead of waiting for each one's next
3	// hourly slot. It fires each member's OWN scheduler with `FORCE_TASKS=baselining` —
4	// the same button the owner would press in that repo's Actions tab, pressed across
5	// the fleet in one run. Nothing is baselined here: each member converges its own
6	// mount, with its own token, under its own scheduler and its own delivery policy.
7	// This is a dispatcher, not a maintainer — the fan-out model this pack runs both its
8	// write-shaped operations on (#749).
9	//
10	// IT DOES NOT WAIT. A dispatch queues a run; what the queued run then does is that
11	// member's own story, told where a member always tells it — its maintenance PR, its
12	// dispatch issues, its own failure escalation. The old workflow's FOLLOW half (watch
13	// every forced member to a terminal state, render a fleet report) was the reason the
14	// lever had to be a standalone workflow with a 45-minute sleep in it; giving the
15	// report up is what lets the lever be an ordinary manual task on the ordinary
16	// scheduler instead of a managed `.github/` copy only the slow agent path could sync
17	// (#649). The run's deliverable is the dispatch table: which members were fired,
18	// which were skipped and why, which refused.
19	//
20	// WHY IT EXISTS. Under per-project scheduling every member baselines itself hourly,
21	// so the fleet needs no push in the ordinary case. The cases it is FOR are the
22	// un-ordinary ones: a canon change the fleet should pick up now rather than over the
23	// next day, and the tail of members whose next slot is hours away. A forced run
24	// bypasses baselining's precondition (the engine records it as forced), so a member
25	// with nothing to do converges to a cheap no-op — safe to over-use, only wasteful.
26	//
27	// THE TOKEN. FLEET_GITHUB_TOKEN, the same account-spanning PAT the sweeps use, plus
28	// ONE scope the read-only ones do not need: **Actions: read and write** on the
29	// owner's repositories. Dispatching another repo's workflow is a write to that
30	// repo's Actions, and a PAT scoped only for the sweeps gets a 403 here — reported
31	// per repo and failing the run, because it is a grant to fix once, not a transient.
32	//
33	// Dependency-free (global fetch, Node 20+). It writes NOTHING to any member — no
34	// commit, no issue, no comment; the single side effect per member is one queued
35	// Actions run.
36	
37	import { appendFileSync } from 'node:fs';
38	import { pathToFileURL } from 'node:url';
39	import {
40	  makeGh, paged, readDeclaration, isDormant, DECLARATION, SCHEDULER, fireScheduler,
41	} from '../../fleet-api.mjs';
42	import { parseSheepdogConfig } from '../../fleet-config.mjs';
43	
44	// The exact member-side task this lever forces — the vendored scheduler's public
45	// surface (`forcedTaskIds` in engine/scheduler/run.mjs); named as a constant so the
46	// coupling is one line to find, not a string buried in a request body.
47	//
48	// `update` since Phase 5 (#768): the task this lever used to force no longer exists,
49	// and a lever that dispatches a task nothing will run reports a successful dispatch
50	// for a member that then does nothing — the exact "counts dispatches, not outcomes"
51	// blindness this sweep already has (Sheepdog#172). The task's own NAME is still the
52	// old vocabulary; renaming it is the fleet-wide update lever's work, not this line's.
53	export const FORCED_TASK = 'update';
54	
55	// The `REPOS` parameter, resolved against the owner: a space/whitespace-separated list
56	// of bare names or full `owner/name`, lowercased, or null for "every member". A bare
57	// name is qualified with the configured owner, because that is the only owner this
58	// sweep can reach and typing it twenty times is friction with no upside.
59	// Space-separated, never comma-separated — the override bag splits keys on commas.
60	export function parseRepoFilter(raw, owner) {
61	  const names = String(raw ?? '').split(/\s+/).map((s) => s.trim()).filter(Boolean);
62	  if (!names.length) return null;
63	  return new Set(names.map((n) => (n.includes('/') ? n : `${owner}/${n}`).toLowerCase()));
64	}
65	
66	// Why a repo is out of this dispatch's scope BEFORE its declaration is even read —
67	// or null when it is in scope. Every branch lands in the report's skipped list,
68	// never a silent `continue`: the report enumerates the full fleet, and a fleet-wide
69	// force whose report names only the dispatched members reads as fleet-wide coverage
70	// when it was not. (Canon is skipped because its baselining self-skips — but the
71	// enforcer repo is NOT exempt: it is an ordinary member with a mount to converge,
72	// and leaving it out would make the one repo the owner is looking at the one repo
73	// that did not move.) Kept free of I/O so every branch is testable directly.
74	export function classifyScope(r, { canonRepo, exclude, filter }) {
75	  const fullName = r.full_name.toLowerCase();
76	  if (fullName === canonRepo.toLowerCase()) {
77	    return { state: 'canon', detail: 'canon has no vendored mount — forcing it would queue a run whose only outcome is its own self-skip' };
78	  }
79	  if (r.archived || r.fork) return { state: 'out-of-scope', detail: r.archived ? 'archived' : 'a fork' };
80	  if (exclude.has(fullName)) return { state: 'excluded', detail: "on the sheepdog config's exclude list" };
81	  if (filter && !filter.has(fullName)) return { state: 'filtered-out', detail: "not in this run's REPOS filter" };
82	  return null;
83	}
84	
85	// --- main ---------------------------------------------------------------------
86	
87	export async function main() {
88	  const token = process.env.FLEET_GITHUB_TOKEN;
89	  const home = process.env.GITHUB_REPOSITORY;
90	  if (!token) {
91	    throw new Error('FLEET_GITHUB_TOKEN is not set. Add a repo secret with a fine-grained PAT '
92	      + '(this account, ALL repositories, Metadata read, Contents read, and Actions READ AND WRITE) — '
93	      + 'the default GITHUB_TOKEN sees only this repo and cannot dispatch another repo\'s workflow.');
94	  }
95	  if (!home || !home.includes('/')) throw new Error('GITHUB_REPOSITORY is not set (owner/repo)');
96	  const gh = makeGh(token);
97	
98	  const dryRun = String(process.env.FLEET_BASELINE_DRY_RUN ?? '').toLowerCase() === 'true';
99	  const includeDormant = String(process.env.FLEET_BASELINE_INCLUDE_DORMANT ?? '').toLowerCase() === 'true';
100	
101	  const cfgRes = await gh(`/repos/${home}/contents/${DECLARATION}`);
102	  if (cfgRes.status !== 200 || !cfgRes.json?.content) {
103	    throw new Error(`the sheepdog repo ${home} has no readable ${DECLARATION} (status ${cfgRes.status})`);
104	  }
105	  let cfg;
106	  try { cfg = JSON.parse(Buffer.from(cfgRes.json.content, 'base64').toString('utf8')); } catch (e) {
107	    throw new Error(`unparsable ${DECLARATION} on ${home}: ${e.message}`);
108	  }
109	  const { owner, exclude, canonRepo } = parseSheepdogConfig(cfg, home);
110	  const filter = parseRepoFilter(process.env.FLEET_BASELINE_REPOS, owner);
111	
112	  const mine = (await paged(gh, '/user/repos?affiliation=owner'))
113	    .filter((r) => r.owner.login.toLowerCase() === owner);
114	  if (mine.length === 0) {
115	    throw new Error(`enumeration returned no repos owned by ${owner} — wrong token user or scope`);
116	  }
117	
118	  const fired = []; const skipped = []; const failed = [];
119	  for (const r of mine.sort((a, b) => a.name.localeCompare(b.name))) {
120	    const fullName = r.full_name.toLowerCase();
